<script setup>
import { useI18n } from "vue-i18n";
import { checkResponseData, arrToDict, currencyFormat, isEMpty , errorMessage} from "@/util/index.js"


const { t } = useI18n();
const isMobile = useIsMobile()
const attrs = useAttrs()
const { tradeOrderApi } = useApi()
const props = defineProps({
  orderId: {
    type: String,
    default: ''
  }
})


const reload = () => {
    window.location.reload()
}
const cancel = () => {
    const fn = attrs['onUpdate:modelValue']
    fn && fn(false)
}


const shippingStatusData = computed(() => {
  return [
    { value: 0, label: t('wallet.trackShipmentDialogStatusNotShipped'), type: 'info' },
    { value: 1, label: t('wallet.trackShipmentDialogStatusShipped'), type: 'primary' },
    { value: 2, label: t('wallet.trackShipmentDialogStatusDelivered'), type: 'success' },
  ]
})
const shippingStatusDict = computed(() => {
  return arrToDict(shippingStatusData.value)
})
const shippingStatusToType = computed(() => {
  return arrToDict(shippingStatusData.value, { label: 'type' })
})
const shippingInfo = ref({
  shippingStatus: undefined,
  logisticsList: []
})
const isGetData = ref(false)
// 查询分销订物流信息
const getOrderShippingInfo = async() => {
  const result = await tradeOrderApi.getOrderShippingInfo({ orderId: props.orderId })
  const res = checkResponseData(result)
  shippingInfo.value = res || { logisticsList: [] }
  isGetData.value = true
}


onMounted(() => {
  getOrderShippingInfo()
})

</script>

